SELECT ?zone ?zoneLabel ?point ?uri WHERE {
  ?ahu brick:hasTag "AHU02" .
  ?zone brick:isServedBy ?ahu .
  OPTIONAL { ?zone rdfs:label ?zoneLabel . }
  ?point brick:hasSubordinate ?zone .
  ?point ref:hasExternalReference ?uri .
  FILTER (regex(str(?point), "AirTemperature", "i") || rdf:type(?point) = brick:ZoneAirTemperatureSensor)
}

